import {useAsyncList} from 'alinea/components'

const list = useAsyncList({
  async load({cursor, filterText, sort, signal}) {
    const res = await fetch(`/api/products?page=${cursor ?? 1}`, {signal})
    const {items, next} = await res.json()
    // Leave out the cursor, or return null, on the last page
    return {items, cursor: next}
  }
})
